-- V303 — the 2026/2027 admission settings as configured on the production database (CAC/2026/07): the session
-- policy, the four selection criteria, the faculty quotas, and every programme's requirements (cut-off, O'Level
-- rule, subject groups). Exported so that a fresh or rebuilt database starts with them and nobody sets them again.
--
-- It loads only when the target has NO 2026/2027 policy: a database that already holds settings for the session
-- (production itself, or one configured by hand) is never overwritten.
-- The invented 2098/2099 demonstration policy is not exported.

BEGIN;

DO $mig$
BEGIN
    PERFORM set_config('moaum.actor_id', '00000000-0000-0000-0000-000000000000', true);
    PERFORM set_config('moaum.actor_office', 'academic', true);
    PERFORM set_config('moaum.reason',
        'The 2026/2027 admission settings, CAC/2026/07, carried from production (V303)', true);

    IF EXISTS (SELECT 1 FROM admissions.session_policy WHERE session = '2026/2027') THEN
        RETURN;
    END IF;

END $mig$;

COMMIT;
